    left = runs([grid[r][0] for r in range(h)])
    right = runs([grid[r][w - 1] for r in range(h)])
    for a in left:
        for b in right:
            if a[0] == b[0]:
                candidates.append((a[2]-a[1] + b[2]-b[1], "horizontal", "left", a, "right", b))
    # Vertical beams: horizontal bars on top/bottom, slot coordinate is column.
    top, bottom = runs(grid[0]), runs(grid[h - 1])
    for a in top:
        for b in bottom:
            if a[0] == b[0]:
                candidates.append((a[2]-a[1] + b[2]-b[1], "vertical", "top", a, "bottom", b))
    if not candidates:
        return out
    _, beam, side_a, run_a, side_b, run_b = max(candidates, key=lambda x: x[0])
    bar_color, a0, a1 = run_a
    _, b0, b1 = run_b
    n = min(a1 - a0, b1 - b0)

    signals = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color == bar_color:
                continue
            pos = r if beam == "horizontal" else c
            options = []
            if a0 <= pos < a0 + n:
                options.append((0, pos - a0))
            if b0 <= pos < b0 + n:
                options.append((1, pos - b0))
            if not options:
                continue
            if len(options) == 1:
                edge, slot = options[0]
            else:
                # If paired runs overlap, associate the signal with the nearer bar.
                da = c if side_a == "left" else w - 1 - c if side_a == "right" else r if side_a == "top" else h - 1 - r
                db = c if side_b == "left" else w - 1 - c if side_b == "right" else r if side_b == "top" else h - 1 - r
                edge, slot = options[0] if da <= db else options[1]
            signals.append((r, c, color, edge, slot))

